const body = $input.first().json.body ?? $input.first().json;

const rawCalendarId = body?.calendar_source_id;
if (rawCalendarId === undefined || rawCalendarId === null || String(rawCalendarId).trim() === '') {
  throw new Error('Campo calendar_source_id es requerido');
}
const calendarSourceId = parseInt(String(rawCalendarId).trim(), 10);
if (Number.isNaN(calendarSourceId)) throw new Error(`calendar_source_id inválido: ${rawCalendarId}`);

const rawIds = Array.isArray(body?.user_ids) ? body.user_ids : [];
const uuidRe = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
const cleanIds = [...new Set(rawIds.map((x) => String(x).trim()).filter(Boolean))];
for (const id of cleanIds) {
  if (!uuidRe.test(id)) throw new Error(`user_id inválido: ${id}`);
}
const userIdsSql = cleanIds.map((id) => `'${id}'`).join(',');

return [{ json: { calendar_source_id: calendarSourceId, user_ids_sql: userIdsSql, count: cleanIds.length } }];
